def wait_idle(app):
    deadline = time.monotonic() + 15
    while app.busy and time.monotonic() < deadline:
        time.sleep(0.02)
    assert not app.busy


class Clock:
    def __init__(self):
        self.t = time.monotonic()

    def step(self, app, square, triangle, dt=1 / 30):
        self.t += dt
        app.camera.image = scene(square=square, triangle=triangle)
        app._process(app.camera.image, self.t)


def act(app, action, **data):
    app.act(action, data)
    wait_idle(app)


def to_units(app, p):
    return cv2.perspectiveTransform(np.array([[p]], np.float32), app.arena.h)[0, 0]


def to_camera(app, p):
    return cv2.perspectiveTransform(np.array([[p]], np.float32), np.linalg.inv(app.arena.h))[0, 0]


def frames(app, n=STABLE_FRAMES + 1, **robots):
    app.camera.image = scene(**robots)
    for _ in range(n):
        app._process(app.camera.image, time.monotonic())


def register(app, names=("Kiste", "")):
    with pytest.raises(UserError):
        app.act("new_battle", {})
    app.act("corners", {"points": [list(c) for c in CORNERS]})
    assert app.phase == "register", app.message
    with pytest.raises(UserError):
        app.act("start", {"names": list(names)})
    # Beide stehen schon: ohne Klick und ohne Leerbild sind beide erkannt, links ist Roboter 1.
    frames(app, square=(220, 200), triangle=(420, 300))
    assert all(p is not None for p in app.proposal)
    assert app.proposal[0][:, 0].mean() < app.proposal[1][:, 0].mean()
    act(app, "start", names=list(names))
    assert app.phase == "fight", app.message
    assert [p.name for p in app.game.players] == ["Kiste", "Roboter 2"]


def hp(app, pid):
    return app.game.player(pid).hp


def test_full_battle(app):
    register(app)
    clock = Clock()
    sq, tri = np.array([220.0, 200.0]), np.array([420.0, 300.0])
    for _ in range(10):
        clock.step(app, sq, tri)
    assert hp(app, 1) == hp(app, 2) == 100

    # Kiste rammt das stehende Dreieck: nur das Dreieck verliert Leben.
    while not app.contact:
        sq += (tri - sq) / np.linalg.norm(tri - sq) * 12
        clock.step(app, sq, tri)
    for _ in range(5):
        clock.step(app, sq, tri)
    assert hp(app, 2) == 100 - app.cfg.collision_damage
    assert hp(app, 1) == 100

    # Auseinander, Identität muss stimmen.
    for _ in range(15):
        sq += np.array([-8.0, -4.0])
        clock.step(app, sq, tri)
    by_id = {o.id: o for o in app.robots}
    assert by_id[1].pos[0] < by_id[2].pos[0]

    # Hindernis: scharf schalten lassen, dann drauffahren.
    app.act("spawn", {"kind": "obstacle"})
    item = app.game.items[-1]
    target = to_camera(app, item.pos)
    for _ in range(40):
        clock.step(app, sq, tri)
    mover = 1 if np.linalg.norm(target - sq) < np.linalg.norm(target - tri) else 2
    pos = sq if mover == 1 else tri
    before = hp(app, mover)
    for _ in range(80):
        d = target - pos
        if np.linalg.norm(d) > 6:
            pos += d / np.linalg.norm(d) * 6
        clock.step(app, sq, tri)
        if not app.game.items:
            break
    assert hp(app, mover) == before - app.cfg.obstacle_damage

    # Power-up heilt, aber nie über das Maximum.
    app.act("spawn", {"kind": "powerup"})
    target = to_camera(app, app.game.items[-1].pos)
    mover = 1 if np.linalg.norm(target - sq) < np.linalg.norm(target - tri) else 2
    pos = sq if mover == 1 else tri
    before = hp(app, mover)
    for _ in range(80):
        d = target - pos
        if np.linalg.norm(d) > 6:
            pos += d / np.linalg.norm(d) * 6
        clock.step(app, sq, tri)
        if not app.game.items:
            break
    assert hp(app, mover) == min(100, before + app.cfg.powerup_heal)

    # Ringout: Dreieck fährt links halb aus der Arena und bleibt 2 s so stehen.
    while tri[0] > 80:
        step = min(10.0, tri[0] - 80)
        tri += np.array([-step, 0.0]) if abs(tri[1] - 300) < 5 else np.array([0.0, np.sign(300 - tri[1]) * 5])
        clock.step(app, sq, tri)
    before = hp(app, 2)
    for _ in range(60):
        clock.step(app, sq, tri)
    lost = before - hp(app, 2)
    expected = (2 - app.cfg.ringout_grace_s) * app.cfg.ringout_hp_per_s
    assert expected - 1 < lost <= 2 * app.cfg.ringout_hp_per_s + 0.5
    assert app.game.player(2).outside_since is not None

    # Zustand muss als Paket rausgehen und lesbar sein.
    app._publish(app.camera.image, 1)
    packet = app.packet[1]
    n = int.from_bytes(packet[:4], "little")
    state = json.loads(packet[4:4 + n])
    W, H = app.arena.size
    assert state["phase"] == "fight"
    assert state["frame"] == {"w": round(W, 1), "h": round(H, 1), "kind": "arena", "pad": VIEW_PAD}
    assert max(W, H) == pytest.approx(1000) and state["proposal"] == []
    # Alles in Arena-Einheiten: der Roboter links liegt nahe der linken Kante.
    xs = [p[0] for r in state["robots"] for p in r["contour"]]
    assert min(xs) < 50 and max(xs) <= W + 1
    assert {r["name"] for r in state["robots"]} == {"Kiste", "Roboter 2"}
    assert any(r["outside"] for r in state["robots"])
    assert packet[4 + n:6 + n] == b"\xff\xd8"

    # Ganz hinausgefahren: K.o., egal wie viel HP noch übrig sind.
    for x in range(70, 0, -10):
        clock.step(app, sq, (x, 300))
    for _ in range(int(1.5 * 30)):
        clock.step(app, sq, (0, 300))
    assert app.phase == "finished" and app.game.winner == 1 and hp(app, 2) == 0


def test_ko_finishes(app):
    register(app)
    clock = Clock()
    app.game.player(2).hp = 1
    # Sprung quer durch die Arena, halb ?ber die Kante: Identit?t bleibt, Position springt mit.
    for _ in range(90):
        clock.step(app, (220, 200), (82, 300))
    assert {o.id: o.present for o in app.robots} == {1: True, 2: True}
    assert app.phase == "finished"
    assert app.game.winner == 1
    with pytest.raises(UserError):
        app.act("spawn", {"kind": "obstacle"})
    app.act("abort", {})
    assert app.phase == "register" and app.game is None


def test_intro_delays_fight_and_timer_counts_up(app):
    app.cfg.intro_s = 5.0
    app.act("corners", {"points": [list(c) for c in CORNERS]})
    frames(app, square=(220, 200), triangle=(420, 300))
    act(app, "start", names=["A", "B"])
    assert app.phase == "intro" and app.game is None
    state = app.state(time.monotonic())
    assert state["intro"] > 4 and state["elapsed"] is None and state["vs"] is False
    with pytest.raises(UserError):
        app.act("spawn", {"kind": "obstacle"})
    with pytest.raises(UserError):
        app.act("start", {"names": []})
    clock = Clock()
    clock.step(app, (220, 200), (420, 300))
    # Namen stehen schon während des Intros, damit die Bühne sie zeigen kann.
    assert [r["name"] for r in app.state(clock.t)["robots"]] == ["A", "B"]
    clock.step(app, (220, 200), (420, 300), dt=5.0)
    # Nach dem Intro-Video bleibt der VS-Bildschirm, bis die Moderation erneut Start drückt.
    clock.step(app, (220, 200), (420, 300), dt=60.0)
    assert app.phase == "ready" and app.game is None and app.state(clock.t)["vs"] is True
    app.act("start", {"names": []})
    state = app.state(time.monotonic())
    assert app.phase == "countdown" and state["vs"] is False and state["countdown"] > 2
    clock.t = time.monotonic()
    clock.step(app, (220, 200), (420, 300), dt=3.0)
    assert app.phase == "fight" and app.game is not None
    assert app.state(clock.t)["vs"] is False
    clock.step(app, (220, 200), (420, 300), dt=2.0)
    assert app.state(clock.t)["elapsed"] == 2.0
    app.act("abort", {})
    assert app.state(clock.t)["elapsed"] is None


def test_click_swaps_assignment(app):
    app.act("corners", {"points": [list(c) for c in CORNERS]})
    frames(app, square=(220, 200), triangle=(420, 300))
    # Rechtsklick (Roboter 2) auf den linken: beide tauschen, ohne dass der zweite angeklickt wird.
    act(app, "pick", x=float(to_units(app, (220, 200))[0]), y=float(to_units(app, (220, 200))[1]), slot=2)
    frames(app, square=(220, 200), triangle=(420, 300))
    assert app.proposal[1][:, 0].mean() < app.proposal[0][:, 0].mean()
    act(app, "start", names=["Rechts", "Links"])
    clock = Clock()
    for _ in range(5):
        clock.step(app, (220, 200), (420, 300))
    by_id = {o.id: o for o in app.robots}
    assert by_id[2].pos[0] < by_id[1].pos[0]
    assert app.game.player(2).name == "Links"


def test_proposal_follows_moving_robot(app):
    app.act("corners", {"points": [list(c) for c in CORNERS]})
    frames(app, square=(220, 200), triangle=(420, 300))
    # Beim Aufstellen wird geschoben: die Zuordnung springt nicht.
    sq = np.array([220.0, 200.0])
    for _ in range(25):
        sq += (8.0, -2.0)
        frames(app, 1, square=sq, triangle=(420, 330))
    assert np.linalg.norm(app.proposal[0].mean(axis=0) - to_units(app, sq)) < 30


