def test_raw_camera_until_corners_then_arena_with_margin(app):
    app._publish(app.camera.image, 1)
    n = int.from_bytes(app.packet[1][:4], "little")
    assert json.loads(app.packet[1][4:4 + n])["frame"]["kind"] == "camera"
    app.act("corners", {"points": [list(c) for c in CORNERS]})
    app._publish(app.camera.image, 2)
    n = int.from_bytes(app.packet[1][:4], "little")
    jpeg = cv2.imdecode(np.frombuffer(app.packet[1][4 + n:], np.uint8), cv2.IMREAD_COLOR)
    W, H = app.arena.size
    assert abs(jpeg.shape[1] / jpeg.shape[0] - (W + 2 * VIEW_PAD) / (H + 2 * VIEW_PAD)) < 0.02
    app.act("reset_arena", {})
    assert app.phase == "arena" and app.tracker is None


