def test_profile_reaches_state_and_keeps_fight_name(app):
    app.act("corners", {"points": [list(c) for c in CORNERS]})
    app.act("profile", {"player": 2, "name": " Kiste ", "team": "Pappe", "weight": "850 g",
                        "image": "/media/1"})
    state = app.state(time.monotonic())
    assert state["vs"] is False and state["names"][1] == "Kiste"
    assert state["profiles"][1] == {"image": "/media/1", "team": "Pappe", "weight": "850 g",
                                    "height": "", "slogan": ""}
    with pytest.raises(UserError):
        app.act("profile", {"player": 3})
    with pytest.raises(UserError):
        app.act("profile", {"player": 1, "color": "rot"})
    frames(app, square=(220, 200), triangle=(420, 300))
    act(app, "start", names=["A", "B"])
    app.act("profile", {"player": 1, "name": "Neu", "slogan": "Los!"})
    state = app.state(time.monotonic())
    assert state["names"][0] == "A" and state["profiles"][0]["slogan"] == "Los!"


def test_cue_toggles_each_meme_and_checks_kind(app):
    a = {"url": "/media/1", "name": "x.mp3", "mime": "audio/mpeg"}
    b = {"url": "/media/2", "name": "y.webm", "mime": "video/webm", "cutout": True}
    assert app.state(time.monotonic())["memes"] == []
    app.act("cue", {"kind": "media", "media": a})
    app.act("cue", {"kind": "media", "media": b})
    memes = app.state(time.monotonic())["memes"]
    assert [m["media"]["url"] for m in memes] == ["/media/1", "/media/2"]
    assert all(0 <= m["x"] <= 1 and 0 <= m["y"] <= 1 and "paused" not in m for m in memes)
    # Zweiter Klick stoppt nur dieses Meme, dritter startet es neu von vorn.
    app.act("cue", {"kind": "media", "media": a})
    assert [m["media"]["url"] for m in app.state(time.monotonic())["memes"]] == ["/media/2"]
    app.act("cue", {"kind": "media", "media": a})
    again = app.state(time.monotonic())["memes"]
    assert [m["media"]["url"] for m in again] == ["/media/2", "/media/1"]
    assert again[1]["id"] != memes[0]["id"] and again[1]["played"] < 0.5
    app.act("cue", {"kind": "ended", "id": memes[1]["id"]})
    assert [m["media"]["url"] for m in app.state(time.monotonic())["memes"]] == ["/media/1"]
    app.act("cue", {"kind": "stop"})
    assert app.state(time.monotonic())["memes"] == []
    with pytest.raises(UserError):
        app.act("cue", {"kind": "media"})
    with pytest.raises(UserError):
        app.act("cue", {"kind": "ko"})


