def test_ko_button_ends_fight_for_that_robot(app):
    app.act("corners", {"points": [list(c) for c in CORNERS]})
    with pytest.raises(UserError):
        app.act("ko", {"player": 2})
    frames(app, square=(220, 200), triangle=(420, 300))
    act(app, "start", names=["A", "B"])
    app.act("ko", {"player": 2})
    state = app.state(time.monotonic())
    assert app.phase == "finished" and state["winner"] == "A"
    assert hp(app, 2) == 0 and hp(app, 1) > 0
    assert [e for e in state["events"] if e["type"] == "ko"][-1]["players"] == [2]
